def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    last_me, last_opp = history[-1]
    if n <= 10:
        return 'D' if last_opp == 'D' else 'C'

    opp_d_total = 0
    my_d_total = 0
    for a, b in history:
        if b == 'D':
            opp_d_total += 1
        if a == 'D':
            my_d_total += 1

    recent_len = 10 if n >= 10 else n
    start = n - recent_len
    recent_opp_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    if last_opp == 'D':
        if last_me == 'C' and opp_d_total * 15 <= n and recent_opp_d <= 1:
            return 'C'
        prev_me, prev_opp = history[-2]
        if prev_me == 'D' and prev_opp == 'C':
            if last_me == 'C' or opp_d_total * 8 <= n:
                return 'C'

    if last_me == 'D' and last_opp == 'D':
        prev_me, prev_opp = history[-2]
        if prev_me == 'D' and prev_opp == 'C' and opp_d_total * 6 <= n:
            return 'C'
        if opp_d_total * 5 <= n and recent_opp_d <= 2:
            return 'C'

    c_count = [0, 0, 0, 0]
    d_count = [0, 0, 0, 0]
    for i in range(n - 1):
        a, b = history[i]
        s = (0 if a == 'C' else 2) + (0 if b == 'C' else 1)
        if history[i + 1][1] == 'D':
            d_count[s] += 1
        else:
            c_count[s] += 1

    scale = 1000
    overall_d = opp_d_total * scale // n
    recent_d = recent_opp_d * scale // recent_len if recent_len > 0 else 0
    base = (overall_d * 3 + recent_d * 7) // 10

    if base < 70:
        priorD = [80, 450, 650, 700]
    elif base < 200:
        priorD = [140, 550, 680, 730]
    elif base < 450:
        priorD = [240, 680, 750, 800]
    elif base < 700:
        priorD = [350, 780, 840, 880]
    else:
        priorD = [450, 850, 900, 940]

    prior_w = 4
    c_num = [0, 0, 0, 0]
    d_num = [0, 0, 0, 0]
    tot_num = [0, 0, 0, 0]
    for s in range(4):
        d_num[s] = d_count[s] * scale + priorD[s] * prior_w
        c_num[s] = c_count[s] * scale + (scale - priorD[s]) * prior_w
        tot_num[s] = c_num[s] + d_num[s]

    payCC = 3 * scale
    payCD = 0
    payDC = 5 * scale
    payDD = 1 * scale

    remaining = 100 - n
    vals = [0, 0, 0, 0]
    for _ in range(remaining - 1):
        nv = [0, 0, 0, 0]
        for s in range(4):
            cn = c_num[s]
            dn = d_num[s]
            tn = tot_num[s]
            vC = (cn * (payCC + vals[0]) + dn * (payCD + vals[1])) // tn
            vD = (cn * (payDC + vals[2]) + dn * (payDD + vals[3])) // tn
            nv[s] = vC if vC >= vD else vD
        vals = nv

    cur = (0 if last_me == 'C' else 2) + (0 if last_opp == 'C' else 1)
    cn = c_num[cur]
    dn = d_num[cur]
    tn = tot_num[cur]
    vC = (cn * (payCC + vals[0]) + dn * (payCD + vals[1])) // tn
    vD = (cn * (payDC + vals[2]) + dn * (payDD + vals[3])) // tn

    if n < 40:
        eps = 800
    elif n < 70:
        eps = 450
    else:
        eps = 250

    if vC + eps >= vD:
        return 'C'
    return 'D'
